const test=require('node:test');
const assert=require('node:assert/strict');
const {subtract}=require('../stock.cjs');
test('multiplicity and stable order',()=>{
  const stock=['a','b','a','c','a'],sent=['a','a','absent'];
  assert.deepEqual(subtract(stock,sent),['b','c','a']);
  assert.deepEqual(stock,['a','b','a','c','a']);
  assert.deepEqual(sent,['a','a','absent']);
  assert.deepEqual(subtract(['x'],['x','x']),[]);
  assert.deepEqual(subtract([],['x']),[]);
  assert.deepEqual(subtract(['__proto__','constructor','','__proto__'],['__proto__','']),['constructor','__proto__']);
  assert.deepEqual(subtract(['a','b'],[]),['a','b']);
});

