exports.subtract = function(stock, shipped) {
  const counts=new Map();
  for(const sku of shipped) counts.set(sku,(counts.get(sku)||0)+1);
  return stock.filter(sku=>{
    const count=counts.get(sku)||0;
    if(!count) return true;
    counts.set(sku,count-1);
    return false;
  });
};

